package com.cryptoloan.shared.web;
import java.net.URI;import java.time.Instant;import java.util.*;import org.springframework.http.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.resource.NoResourceFoundException;
@RestControllerAdvice public class ApiExceptionHandler{record Problem(String type,String title,int status,String detail,Instant timestamp){}private ResponseEntity<Problem>p(HttpStatus s,String title,String detail){return ResponseEntity.status(s).body(new Problem("about:blank",title,s.value(),detail,Instant.now()));}@ExceptionHandler(NoSuchElementException.class)ResponseEntity<Problem>missing(Exception e){return p(HttpStatus.NOT_FOUND,"Ressource introuvable",e.getMessage());}@ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class,MethodArgumentNotValidException.class})ResponseEntity<Problem>bad(Exception e){return p(HttpStatus.BAD_REQUEST,"Requête invalide",e instanceof MethodArgumentNotValidException?"Les données fournies sont invalides":e.getMessage());}@ExceptionHandler({SecurityException.class,AccessDeniedException.class})ResponseEntity<Problem>forbidden(Exception e){return p(HttpStatus.FORBIDDEN,"Accès refusé","Cette opération n'est pas autorisée");}}

